-- Mod-authored great work descriptions, zh_Hant_HK overlay.
-- Baseline in CivVAccess_GreatWorkDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_MISSING"] = "這件偉大作品沒有圖像描述."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LITERATURE"] =
    "燭光搖曳的書房中, 一位作家伏案疾書, 羽毛筆在紙上沙沙滑過, 窗外夜色深沉. 蠟燭的暖光映照出他專注低垂的臉龐, 將他與周圍的陰影隔開, 案頭散落著文稿與墨水瓶."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MUSIC"] =
    "昏暗的音樂廳中, 觀眾屏息靜候, 舞台上的樂手在微弱燈光下各就其位, 弦樂的低鳴在寂靜中緩緩升起, 將整個廳堂籠罩在音樂帶來的莊嚴氛圍之中."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIRL_WITH_PEARL_EARRING"] =
    "荷蘭黃金時代的油畫, 西方藝術中最受喜愛的肖像之一. 一名年輕女子從素淨的深色背景中越過肩頭回望, 與你四目相對, 雙唇微張, 彷彿正要開口. 她戴著一頂藍金兩色的纏頭巾, 布料垂落於背後, 耳畔一顆碩大的淚滴形珍珠映著光."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HENRY_VIII"] =
    "都鐸宮廷油畫肖像, 這幅形象定格了世人心目中的亨利八世. 國王全身正面而立, 雙腳大張, 肩寬體胖, 一手按在腰間的匕首上. 他內穿一件鑲嵌珠寶的銀色緊身上衣, 外罩一件襯有毛皮的深紅色長袍, 頭戴一頂插羽的平頂帽, 佩著金鏈, 站在兩根大理石柱之間的花紋地毯上."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HUNTERS_IN_THE_SNOW"] =
    "法蘭德斯文藝復興油畫, 從山頂俯瞰的冬日風景. 三名疲憊的獵人和他們的獵犬群在前景的深雪中艱難跋涉, 低垂著頭, 整場狩獵只獵得一隻狐狸. 在他們下方, 一座村莊在灰綠色的天空下鋪展開來, 結冰的池塘上有渺小的溜冰者在玩耍, 嶙峋的山峰在遠處聳立."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LES_DEMOISELLES"] =
    "早期現代主義油畫, 開創立體主義的那幅畫. 五名裸女在一個由粉紅, 白色和藍色稜角平面構成的淺空間中站立和坐臥, 她們的身體被分解成尖銳的稜角形狀. 右側兩張臉畫得像非洲面具, 滿是條紋與扭曲, 其餘的則睜著杏仁狀的大眼睛直直望出; 畫面底邊放著一小碗水果."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LUNCHEON"] =
    "法國印象派油畫, 描繪一群朋友餐後流連的情景. 一群衣著夏裝的人聚在河畔的露台上, 頭頂是橙白相間的條紋遮陽篷, 他們交談, 調笑, 倚著欄杆; 前方一名年輕女子在逗弄一隻小狗. 桌上散落著酒瓶, 酒杯和水果, 全以溫暖, 鬆散的陽光色彩筆觸繪成."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MONA_LISA"] =
    "意大利文藝復興時期的木板油畫, 大概是世上最著名的肖像. 一名女子雙手交疊而坐, 略略轉向你, 背景是迷濛的風景, 蜿蜒的河流和遠處的藍色山巒. 她的雙眼與你直接對望, 那著名的目光彷彿無論你站在何處都會追隨著你. 她那淡淡的半笑是整幅畫的焦點, 以柔和的褐色和綠色繪成, 沒有硬朗的輪廓線, 因此你看得越久, 她的神情彷彿越是流轉變化."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUNDAY_AFTERNOON"] =
    "點彩派油畫, 完全由純色的細小圓點構成. 巴黎人穿著最好的禮拜日盛裝, 在陽光普照的河畔草地上休憩, 撐著陽傘散步, 在草地上慵懶斜臥, 牽著小狗行走, 身後水面上有帆船. 每個人都出奇地靜止而拘謹, 像浮雕中的人物, 光線被分解成綠色, 橙色和紫色斑點的閃爍."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VIEW_OF_TOLEDO"] =
    "西班牙文藝復興油畫, 西方藝術中最早的純風景畫之一, 也是格外陰鬱的一幅. 西班牙的山城托勒多在猛烈的暴風天空下於遠處聳起, 灰色的尖塔和城牆被一種詭異的銀色光線映照. 綠色的山丘向前景的一條河流綿延而下, 整個場景以深綠和藍黑色繪成, 與其說是日光, 不如說更像夢境."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WATER_LILIES"] =
    "法國印象派油畫, 出自莫內描繪其吉維尼花園池塘的著名系列. 整幅畫布就是水面, 沒有地平線, 也沒有岸邊: 一片片綠色睡蓮葉漂浮在藍色和淡紫色的水面上, 點綴著粉紅和紅色的花朵. 雲和樹只以柔和的倒影呈現, 筆觸鬆散得讓一切彷彿都在漂浮."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_STARRY_NIGHT"] =
    "後印象派油畫, 現代藝術中最為人熟知的形象之一. 一片充滿動感的夜空佔據了畫布大部分: 群星在旋轉的光暈中燃燒, 月亮在一角橙色灼灼, 而一道巨大的螺旋氣流橫掃過夜空中央. 下方, 一座寧靜的村莊和一座尖頂教堂在山丘間沉睡, 一棵深色的柏樹在左緣如火焰般竄起, 全以厚重, 清晰可見的藍色和金色筆觸繪成."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BIRTH_OF_VENUS"] =
    "意大利文藝復興繪畫, 描繪愛神自海中降臨, 是古典神話最著名的形象之一. 維納斯裸身立於一隻巨大的扇貝殼上, 以雙手和一綹長長的金髮遮掩自己. 左側兩位帶翼的風神將她吹向岸邊, 穿過一陣粉紅玫瑰花雨, 右側一名身穿花裙的女子則急忙趕來, 要為她披上一件飄揚的斗篷."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BINDO_ALTOVITI"] =
    "意大利文藝復興盛期的油畫肖像, 描繪一位富有的羅馬年輕銀行家. 一名俊美的年輕男子, 留著長長的金髮, 戴著黑帽, 越過裸露的肩頭回望著你, 一手按在胸前. 他在黑色衣物外披著一件藍色斗篷, 蒼白的臉龐在深綠色的背景前泛著光."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_DRAGON"] =
    "早期意大利文藝復興繪畫, 帶有童話故事般生硬而稚拙的趣味. 右側, 一名披甲的騎士騎在一匹人立而起的白馬上, 將長矛刺入一條帶翼綠龍張開的大口, 那龍生著飛蛾般的斑點翅膀. 左側, 一位身穿粉紅長裙的沉靜公主像牽寵物一樣用韁繩牽著這隻受傷的怪獸, 站在牠陰暗的洞穴前, 而騎士身後則聚起一場奇異的螺旋風暴."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CREATION_OF_ADAM"] =
    "意大利文藝復興濕壁畫, 出自西斯廷禮拜堂的天花板, 是藝術中最著名手勢之一的源頭. 一個裸身的亞當斜倚在左側的綠色山坡上, 一臂無力地伸出, 而上帝, 一位灰鬚的人物, 裹在一件飄揚的, 滿載天使的玫瑰色裹布中, 自右側湧入. 他們伸出的食指越過一道細小的縫隙相互探近, 正是生命火花迸發前的那一瞬間."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GALLERY_OF_THE_LOUVRE"] =
    "美國油畫, 描繪羅浮宮內的一處畫廊, 出自後來發明電報碼的同一位摩斯之手. 一間宏大的紅牆沙龍從地板到天花板掛滿數十幅金框古典大師畫作, 其中包括一幅小小的蒙娜麗莎. 前景中, 學藝的學生坐在畫架前臨摹, 他們的老師俯身越過一名年輕女子的肩頭, 指正她的作品, 遠處一條拱形長廊通向更多畫廊."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WASHINGTON_CROSSING"] =
    "華盛頓勇渡特拉華河, 一幅英雄氣概的美國歷史油畫, 也是美國獨立戰爭的標誌. 華盛頓將軍直立在一艘擠滿人的划艇船首, 他的士兵撐篙划槳, 穿越一條被大塊浮冰堵塞的河流, 他身後一名軍官高舉美國國旗. 黎明的光線穿透冰冷的霧氣, 更多載滿士兵和馬匹的船隻緊隨其後."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ARRANGEMENT_IN_GREY"] =
    "美國油畫, 世人普遍稱之為惠斯勒的母親, 正式名為灰與黑的編排, 藝術家的母親. 一位身穿黑色長裙, 戴白色蕾絲帽的年長女子以嚴整的側面端坐, 面朝左方, 雙手交疊於膝上, 雙腳踏在一張小腳凳上. 房間素淨而平面: 一面灰牆, 一幅深色花紋的帷幔, 以及一幅鑲框的畫, 整幅構圖如同一項灰與黑的研究般均衡, 正如標題所言."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BREEZING_UP"] =
    "乘風而駛, 一幅美國寫實主義油畫, 描繪新英格蘭海岸外的小艇航行. 一名男子和三個男孩在一艘名為格洛斯特的小型平底帆船上向後仰靠, 帆船在勁風中側傾, 浪花從船首濺起, 當日的漁獲堆在他們腳邊. 海面在破碎的雲層下泛着波濤起伏的綠色, 地平線上有一艘雙桅縱帆船."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_THOUSAND_LI"] =
    "千里江山圖, 一幅中國青綠山水長卷, 由宋代宮廷一位少年天才繪於絹上, 長近十二米. 群山以鮮明的礦物藍綠色一嶺接一嶺, 自一條平靜的金色江水中升起, 山坡之間點綴着小小的村莊, 橋樑和枯樹. 一行行運筆的書法和紅色的收藏印章佈滿峰巒之上的天空."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DWELLING_IN_THE_FUCHUN"] =
    "富春山居圖, 一幅中國水墨長卷, 是元代文人山水畫的傑作, 全以紙上濃淡相間的黑墨繪成. 圓潤的山巒由層層乾筆筆觸堆疊而成, 高聳於一條寬闊平靜的江水之上, 兩岸有松樹, 散落的茅舍和漁船. 畫面意境從容而沉思, 紙上佈滿歷代仰慕者數百年來累積的紅色收藏印章."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ALONG_THE_RIVER"] =
    "清明上河圖, 一幅中國宋代絹本長卷, 是描繪城市日常生活的著名全景, 長逾五米. 所示的這一段以京城的大城門為中心, 那是一座聳立於斜坡城牆之上的巨大木樓, 城門下的街道上人聲鼎沸: 市集攤檔, 牛車, 一支穿過城門的駱駝商隊, 以及用扁擔挑着貨物的腳夫. 每個人物都極為細小, 卻以精細的墨線和柔和的土色精準描繪."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LEAF_2"] =
    "二葉, 一幅中國清代冊頁, 是工筆細描, 設色淡雅的宮廷畫. 衣袂飄飄, 身穿白, 綠, 藍色長袍的優雅仕女聚於一座以鮮藍布幔裝飾的園中亭閣, 其中一人在紅色欄杆後的桌旁焚香. 她們周圍是園林山石, 竹子, 以及一株攀爬過亭頂的開花藤蔓."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EMPEROR_TAIZONG"] =
    "步輦圖, 一幅中國唐代絹本長卷, 是一次外交會面的宮廷記錄. 右側, 唐太宗坐在一座由宮女抬着的步輦上, 宮女們還舉着兩把大扇和一頂遮在他頭上的紅色華蓋. 左側, 三個較小的人物以恭敬之姿趨前: 一名身穿紅衣的引見官員, 一名身着花紋袍服的吐蕃使臣, 以及一名身穿白衣的譯員, 全都襯托於佈滿紅色印章的暖金色絹底之上."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SPRING_MORNING"] =
    "漢宮春曉圖, 一幅中國明代絹本長卷, 是描繪宮中女子於春日清晨閒適情景的長幅全景. 數十位優雅仕女遍佈於開敞的殿堂, 迴廊和庭院之間: 奏樂, 繪製肖像, 與孩童嬉戲, 在垂柳, 園林山石乃至孔雀之間漫步. 宮廷建築以暖紅與綠色貫穿整卷, 每一道屏風, 欄杆和衣袍都以一絲不苟的工筆細節呈現."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_GREAT_WAVE"] =
    "神奈川沖浪裏, 一幅日本浮世繪木刻版畫, 是日本藝術中最為著名的單幅圖像. 一道巨大的深藍色海浪在左側高高聳起, 捲過整個畫面, 浪峰碎裂成一根根爪狀的白色泡沫. 浪下, 三艘載滿船夫的細長敞船在波谷間起伏, 而在遠處, 處於這一切的正中央且顯得渺小的, 是富士山積雪的錐形山頂."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EVENING_SHOWER"] =
    "大橋安宅的雷陣雨, 一幅日本浮世繪木刻版畫, 是有史以來最受推崇的雨景之一. 一場驟雨以一片片纖細的斜線繪出, 將正行至一座長木橋中段的人們困在途中; 他們戴着斗笠, 撐着雨傘, 朝兩個方向匆匆趕路, 其中一人躲在一張草蓆下. 橋下的河流是一條青綠色的水帶, 一名孤獨的筏夫撐篙而過, 暴雨之下遠岸漸漸隱沒為一片深色的模糊."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_L_ABSINTHE"] =
    "法國咖啡廳剪影, 一幅法國印象派油畫, 是巴黎咖啡廳生活毫不留情的一幕. 一名身穿淡色衣裙, 戴帽的女子頹然坐在一張大理石咖啡桌旁, 雙眼低垂, 面前擺着一杯乳綠色的苦艾酒; 她身旁一名留鬍鬚的男子身穿皺巴巴的外套, 口中叼着煙斗, 目光望向右方. 兩人坐在一起卻又徹底疏離, 以單調的灰色和褐色繪成, 承載着畫面孤獨的氣息."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_UPAUPA_SCHNEKLUD"] =
    "拉大提琴的男子, 一幅後印象派油畫肖像, 描繪一位演奏中的大提琴手. 樂手俯身於他那把鮮明的橙紅色大提琴之上, 雙眼專注地低垂, 持弓的手臂掠過琴弦, 深藍色的西裝襯托着樂器的光澤. 他身後的背景分割成褐色與苔綠色的平塗色塊, 點綴着淡色的抽象形狀, 呈現出高更大膽而簡化的色彩風格."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_BAR_AT_THE_FOLIES"] =
    "法國現代生活題材油畫, 馬奈最後的傑作. 一名酒吧女侍身穿黑色天鵝絨胸衣, 胸前別著一朵花, 站在一張擺滿香檳酒瓶的大理石櫃台後, 櫃台上還有一碗橙子和一隻插著玫瑰的玻璃杯, 她神情疲憊而恍惚地望向前方. 在她身後, 一面巨大的鏡子映出燈火璀璨的音樂廳, 廳中的吊燈與人群, 而奇怪地偏移到右側的, 是她自己的背影, 她正俯身湊向一名戴高頂禮帽的男子."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BALL_AT_THE_MOULIN"] =
    "描繪這座著名歌舞廳巴黎夜生活的後印象派油畫. 一群戴高頂禮帽的男子和戴羽飾帽的女子圍坐在一張擺著飲料的桌旁, 在他們身後綠光映照的舞廳裡, 一名紅髮女子正整理頭髮. 一張女子的面孔逼近畫面右緣, 自下方被照出幽靈般的綠色, 一道長長的斜向欄杆橫切過前景, 帶有羅特列克海報般的風格."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS"] =
    "以真金箔層疊鋪成的維也納新藝術風格油畫, 克林姆最著名的作品. 一對戀人跪著緊緊相擁於一片開滿花的草地上, 男子俯身親吻女子的臉頰, 女子仰起面龐, 雙眼緊閉. 他們的身體融為一件金色斗篷, 男子那一側飾以矩形紋樣, 女子那一側飾以鮮亮的圓形, 在一片平塗而閃爍的金色背景前熠熠生輝."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AMERICAN_GOTHIC"] =
    "美國地方主義油畫, 被無數次戲仿, 一眼即可辨認. 一名神情嚴肅, 頭頂半禿的農夫戴著圓框眼鏡, 身穿丹寧工裝吊帶褲, 直立著握住一把三齒乾草叉, 身旁一名女子身穿深色印花圍裙連衣裙, 嘴唇緊抿地望向別處, 神色不悅. 他們身後是這幅畫得名所來的白色農舍, 山牆上有一扇尖拱的哥德式窗戶."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SRI_SHANMUKAHA"] =
    "印度宗教畫, 採用拉維·瓦爾馬使其風靡全印度的歐洲學院派風格. 印度教神祇室建陀騎乘他的孔雀坐騎, 有六個戴冠的頭和多條手臂, 手中各持兵器, 兩側是他身穿鮮粉色紗麗的兩位妻子. 孔雀的尾羽在他們身後如一把綠色與金色眼斑的巨扇般展開, 而這隻鳥用爪將一條眼鏡蛇釘壓在腳下."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DAUD_RECEIVES_A_ROBE"] =
    "出自一部配圖帝國編年史的蒙兀兒細密畫, 以紙上不透明水彩和金繪成. 所展示的細部以一名身形纖細的年輕侍從為中心, 他身穿淡色長袍, 戴紅帽, 繫金色腰帶, 為授袍儀式捧著那件折疊好的金色榮譽之袍. 他立於一面亮藍色帳幕牆前, 牆上遍布纖巧的花蔓, 每一道褶皺與每一朵花都以細密畫的精準筆觸繪出."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YUSEF_AND_ZULEYKHA"] =
    "出自一部配圖手抄本的波斯細密畫, 偉大的赫拉特大師畢札德最負盛名的作品. 整頁被一座以平面化剖面呈現的繁複宮殿填滿, 宛如一座由樓梯, 陽台和門洞構成的迷宮, 鋪以藍, 橙, 金三色的瓷磚. 在上層一間居室裡, 周身環繞火焰光輪的先知尤瑟夫, 正從祖勒卡伸出的雙手中逃脫, 一塊塊波斯書法面板環框著這座建築."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ASCENT_OF_MUHAMMAD"] =
    "出自一部御用手抄本的波斯細密畫, 描繪先知穿越諸天的夜行登霄. 穆罕默德面覆白紗, 周身環繞金色火焰, 騎乘人首坐騎布拉克, 越過一片綴滿金邊捲雲的深藍色天空. 身穿紅, 綠, 橙各色長袍的天使在他四周翻飛環繞, 捧著禮物與香爐, 一行行波斯詩句環框著這一場景."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LIBERTY_LEADING_THE_PEOPLE"] =
    "法國浪漫主義油畫, 革命的標誌性圖像. 自由女神化身為一名袒胸的女子, 身穿黃色長裙, 頭戴紅帽, 大步跨越一座由瓦礫和倒下屍體堆成的街壘, 將法國三色旗高高擎入煙霧瀰漫的天空. 她周圍湧動著各個階層的武裝市民, 其中有一名戴高頂禮帽, 手持火槍的紳士, 還有一個揮舞著兩把手槍的男孩."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_JEROME_IN_HIS_STUDY"] =
    "文藝復興早期油畫, 細密的精準程度令人驚歎. 透過一道宏偉的石拱門望去, 書房中的聖哲羅姆身穿紅袍, 坐著閱讀, 那間木製書房宛如搭建在一處拱頂大教堂空間內的舞台, 四周環繞著擺滿書籍與陶罐的架子. 光線從四面的窗戶傾瀉而入, 一隻孔雀和一隻鷓鴣棲息在前方的門檻上, 他的獅子在右側的陰影中徘徊."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PARTHENON_FRIEZE"] =
    "維多利亞時代油畫, 想像古代雅典的景象, 在遊戲中這幅作品隨巴特農神廟奇觀一同出現. 雕刻家菲迪亞斯站在一座木製腳手架上, 身旁是他剛剛上色的騎手大理石浮雕, 仍帶著作坊裡的色彩, 他一邊拉住一根繩索, 一邊向眾人展示這件作品. 一小群身穿垂褶長袍的雅典人, 其中包括伯里克利, 在神廟內溫暖的光線下俯身欣賞這件雕刻."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUE_DE_PARIS"] =
    "描繪細雨天現代巴黎的法國寫實主義油畫, 在他那些印象派朋友筆觸鬆散之處, 這幅畫卻清晰如照片. 一對衣著考究的男女共撐一把傘, 朝你走來, 踏過閃著水光的鵝卵石路面, 男子戴著高頂禮帽, 女子身穿深色長裙, 耳環映出光亮. 他們周圍, 其他撐傘的行人正穿過一處寬闊的十字路口, 路口兩旁排列著楔形的灰色公寓樓, 一根綠色路燈柱將整個畫面從中一分為二."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_NIGHT_WATCH"] =
    "尺幅巨大的荷蘭黃金時代油畫, 史上最著名的群像畫. 一支城市民兵連隊從深沉的陰影中迸發而出, 投入行動: 身穿黑衣, 繫紅色綬帶的隊長大步向前, 向他身穿淡金色軍服的副官下達命令, 在他們身後, 火槍正被裝填, 一面旗幟被高高舉起, 一名鼓手在擊鼓打拍. 人群中, 一個身穿閃亮金色裙裝的小女孩神秘地發著光, 在昏暗中如被聚光燈照亮."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DEATH_OF_MARAT"] =
    '法國新古典主義油畫, 法國大革命偉大的殉道者圖像. 革命派記者馬拉死在他的浴缸裡, 像一位倒下的聖徒般癱軟著, 頭上裹著白色頭巾, 一條手臂垂落至地, 手中仍握著他的羽毛筆. 他另一隻手中是兇手用以騙取入內的那封信件; 畫布的上半部分是空蕩的暗色牆面, 他身旁那只素淨的木箱上寫著題獻 "獻給馬拉, 大衛."'
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ETIENNE_CHEVALIER"] =
    "法國中世紀晚期的木板畫, 取自一幅著名宗教雙聯畫的一翼. 王室財政官艾蒂安騎士身着華麗的紅袍跪着, 雙手合十祈禱, 由他的主保聖人聖史蒂芬引介, 後者身披藍金色聖衣立於其旁. 這位聖人手捧一本書, 書上壓着一塊參差的石頭, 象徵他殉道的方式, 兩人立於一座白色大理石廳堂中, 捐贈者的名字沿牆鐫刻."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_FRANCIS"] =
    "西班牙巴洛克油畫, 描繪嚴峻的修道虔誠. 聖法蘭西斯獨自站着, 身穿樸素的沙色連帽修士袍, 面容半隱於兜帽的深影中, 垂目祈禱. 他雙手捧着一具人類頭骨, 以提醒死亡, 在近乎全黑的背景前由一道堅硬的光照亮."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HATAORI"] =
    "日本浮世繪木刻版畫, 描繪一名織女在勞作. 一位年輕女子身穿有花紋的靛藍和服, 赤足坐在一台大型木制手織機前, 從活計中抬眼望出, 一手握着梭子, 紅, 藍, 白三色的線沿織機長度繃展開來. 畫面色調是柔和的米色與沉靜的藍色, 一列手書詩句填滿畫面的左上方."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JANE_GREY"] =
    "法國學院派歷史畫, 富戲劇性而令人心碎. 這位少女王后被蒙住雙眼, 身穿白色緞袍, 在昏暗的石室中熠熠生輝, 跪着盲目摸索行刑斷頭台, 一位年長的官員溫和地引導她的雙手伸向斷頭台. 她的侍女們在她身後的石柱旁悲痛癱倒, 劊子手在右側等候, 倚着他的斧子, 雙眼別開."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WANDERER"] =
    "德國浪漫主義油畫, 是人獨對自然的代表性圖像. 一位年輕男子身穿深綠色外套, 背對着你站在嶙峋的山巔, 倚着一根手杖, 頭髮被風吹動. 在他下方, 一片白霧的海洋吞沒了山谷, 只有山脊與峭壁如島嶼般破霧而出, 蒼白的群山漸隱於遠方."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BABEL"] =
    "弗拉芒文藝復興油畫, 描繪聖經中註定傾覆的巴別塔, 細節繁密. 一座巨大的螺旋塔由拱門構成, 部分是白石, 部分是裸露的紅磚, 歪斜地攀升入雲, 塔頂仍是粗糙未完成的狀態. 塔基周圍鋪展着一座港口城市, 船隻停泊其間, 前景中一位國王正在檢視一隊石匠, 他們跪在他腳下的石塊之間."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YOUNG_LADY"] =
    "早期尼德蘭油畫肖像, 尺幅小巧, 沉靜, 異常地現代. 一位面容如瓷般光滑的蒼白少女戴着高聳的黑色天鵝絨頭飾, 飾以金邊, 側目望向你. 她身穿藍色長袍, 配白色毛皮領子, 頸間是一條由金與黑相間細帶構成的緊頸鏈, 背景是一面樸素昏暗的牆, 而非通常那種深沉的黑色虛空."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_KINDRED"] =
    "美國哈德遜河派油畫, 是對一位畫家與一位詩人之間友誼的致敬. 兩名身穿外套的男子站在凸出於卡茨基爾山林木峽谷之上的岩台上交談, 其中一人手持畫筆指向風景. 一道溪流在下方的岩石上奔瀉, 由懸垂樹木形成的拱形框住, 朦朧的山峰在後方溶入金色的光中."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BLUE_BOY"] =
    "英國大風格油畫肖像, 是這位畫家最著名的作品. 一名約十二歲的男孩全身站立, 身穿閃光的藍色緞質套裝, 配及膝短褲與蕾絲領子, 一手叉腰, 另一手在身側握着一頂插羽的帽子. 他從一片昏暗, 暴風雨將至的褐色風景中望出, 神情自在而自信, 令這身藍色裝束熠熠生輝."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SECOND_OF_MAY"] =
    "西班牙油畫, 是藝術史上最早也最偉大的反戰抗議之一. 在燈籠的光照下, 一支法國行刑隊排成面目模糊的一列, 步槍對準馬德里城外一座荒山上一群擠作一團的西班牙俘虜. 畫面中央, 一名身穿白衫的男子在槍口前張開雙臂, 跪在已被槍決者的屍體之間, 姿態呼應着受難的十字架."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_CART"] =
    "法國軍事油畫, 取材自普法戰爭, 是一幅描繪不屈的最後抵抗的著名圖像. 一小撮法國士兵防守着一棟殘破的村屋, 從窗口開火, 受傷者倚牆癱坐, 一名軍官正清點他們最後的彈藥. 房間一片狼藉, 一扇門被扯離合頁, 灰泥從天花板剝落, 日光從門口灌入, 戰友們仍在那裏奮戰."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EARLY_AUTUMN"] =
    "中國手卷, 以水墨與淡彩繪成, 是一幅凋零荷塘的近景自然寫生. 紅, 綠, 藍色的蜻蜓在乾枯的蘆葦與殘破的荷葉上盤旋, 蚱蜢, 一隻蜜蜂與幾隻小蛙在下方各自忙碌. 畫面的情緒是溫柔的衰朽, 夏日的生命在剛開始枯萎的草木間繼續, 兩側邊緣鈐有紅色的收藏家印章."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_APPRECIATING_LOTUSES"] =
    "日本水墨設色掛軸, 由狩野派的創始人所繪, 以中國文人山水的風格畫成. 一位身着長袍的中國文人乘一葉小舟漂於荷塘邊緣, 凝望浮葉, 身旁一株虬曲的柳樹從嶙峋的岸邊探出. 這幅高掛軸的大部分是霧氣與開闊的水面, 幾叢松頂漸隱於朦朧之中."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EQUESTRIAN_PORTRAIT"] =
    "威尼斯文藝復興油畫, 是其後數世紀君主騎馬像的範本. 這位神聖羅馬皇帝身穿閃亮的全套盔甲, 戴着插紅羽的頭盔, 手持長矛, 騎馬馳出一片昏暗的樹林, 紀念他在米爾貝格的勝利. 他的黑馬披着深紅色馬衣, 一輪低垂的夕陽在沉重的暴風雲下透出金色與粉色的光."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ARMADA"] =
    "都鐸王朝的油畫宣傳肖像, 為慶祝擊敗西班牙無敵艦隊而繪. 伊莉莎白女王身穿一襲綴滿珍珠與蝴蝶結的華貴禮服端坐, 臉龐被一圈巨大的白色蕾絲褶皺領環繞, 一隻手帶著佔有之意按在一個地球儀上, 手指落在美洲. 她身後的窗戶將故事呈現兩次: 一側是平靜海面上的英格蘭艦隊, 另一側是在風暴中失事的西班牙船隻. 她鑲嵌珠寶的王冠擺放在身旁."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRANCIS_I"] =
    "法國文藝復興時期的油畫王室肖像. 法蘭索瓦一世以半身正面朝向觀者, 身著華麗的宮廷盛裝, 白色與金色緞面開衩袖以黑色條紋相間, 胸前橫掛一條金鏈, 頭戴一頂插有白色羽飾的黑帽. 他狡黠, 長鼻, 蓄鬚的臉龐, 在飾有王冠花紋的深紅錦緞背景前格外醒目."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SELF_PORTRAIT"] =
    "魯道夫二世皇帝的佛蘭德斯宮廷畫師所繪的北方矯飾主義油畫自畫像. 畫家越過肩頭回望觀者, 是一位結實, 蓄鬚的男子, 軟黑帽下露出鬈髮, 灰藍色緊身上衣外圍著白色褶皺領. 在素淨的棕色背景前, 筆觸溫暖而直接, 他那審視般的側目凝視攫住觀者的目光."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VERTUMNUS"] =
    "矯飾主義油畫, 是阿爾欽博托最著名的奇想拼合頭像. 這是一幅將魯道夫二世皇帝描繪成羅馬季節之神威耳廷努斯的肖像, 他整張臉與胸膛全由水果, 蔬菜和花卉拼合而成: 豌豆莢的眼瞼, 一個梨子鼻, 櫻桃嘴唇, 麥穗的鬍鬚, 還有葡萄做的頭髮. 遠看是一位威嚴的統治者; 近看則化為一個市集攤檔, 一切都襯在黑色背景之前."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_SUPPER"] =
    "威尼斯文藝復興晚期的油畫, 重新構想了這個熟悉的場景. 最後的晚餐的餐桌並非正面朝向觀者, 而是沿著陡峭的對角線向後沒入一座昏暗的酒館廳堂, 基督在桌身一半處發著光, 把麵包遞給眾使徒. 僕役搬運食物, 前景中一隻貓把頭探進一個籃子, 頭頂上方一盞熊熊燃燒的油燈, 在煙霧瀰漫的空氣中映出半透明, 旋舞的天使."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_A_MAN"] =
    "早期尼德蘭油畫, 可能是畫家本人的面容, 也是最早的真正自畫像之一. 一位中年男子, 面容滿佈皺紋, 目光銳利, 從深沉的陰影中直視觀者, 頭上纏著一頂奢華的紅色頭飾, 盤繞打結成雕塑般的褶層. 細節纖毫畢現, 每一道皺紋, 每一根鬍碴都被捕捉下來, 人物身著一件鑲深色毛皮的外衣, 襯在黑色背景之前."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRONT_OF_THE_MIRROR"] =
    "威尼斯文藝復興時期的油畫, 是年邁的貝里尼寧靜的晚年傑作. 一位赤裸的紅褐色頭髮少婦坐在一塊紅布上, 一邊安詳地梳理頭髮, 一邊手持一面小手鏡, 身後牆上另一面圓鏡映出她那花紋頭飾的背面. 她身旁一扇窗開向碧綠的鄉野, 雲天之下遠處青山隱現."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ADORATION"] =
    "斯克羅威尼禮拜堂的早期意大利濕壁畫, 出自被譽為將自然人性情感重新帶回西方藝術的畫家之手. 在一座木製頂篷之下, 瑪利亞抱著聖嬰基督, 三王中最年長的一位跪下親吻聖嬰的雙足, 王冠擱在一旁; 駱駝在左側等候. 馬廄上方, 一顆彗星劃過深藍色天空, 取代了慣常的星辰, 這一切都以喬托堅實, 簡樸的人物和清澈的色彩呈現."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUBENS_AND_ISABELLA"] =
    "佛蘭德斯巴洛克油畫, 是畫家為自己與新娘所繪的婚禮肖像. 這對年輕夫婦緊挨著坐在一叢忍冬之下, 她的右手溫柔地搭在他的手上, 這是全畫寧靜的中心. 他坐在較高處, 身穿黑色緊身上衣, 一腿交疊; 她跪坐著, 身穿紫色裙裝, 金線刺繡胸衣, 寬大的褶皺領和高頂草帽, 兩人都帶著平靜的滿足向外望去."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CHILDS_BATH"] =
    "描繪日常溫情的美國印象派油畫, 其高視角和平面化的圖案受到日本浮世繪的影響. 一位身穿大膽條紋連衣裙的母親, 把一個裹著毛巾的孩子抱在膝上, 在一盆水中為小傢伙洗腳. 兩人的頭都低下湊在這件事上, 周圍的房間是一床圖案的拼布: 花卉壁紙, 彩繪木箱, 華麗地毯, 還有一個白色水罐."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_CARD_PLAYERS"] =
    "後印象派油畫, 是以此題材聞名的系列之一. 兩個戴帽子的農夫隔著一張小木桌相對而坐, 全神貫注於手中的紙牌, 一瓶酒立在兩人之間, 是構圖中靜止的中心. 一人抽著煙斗; 顏料以耐心, 塊狀的筆觸層層堆疊, 用泥土般的棕色, 赭色和暗淡的紫色, 使人物顯得彷彿雕鑿而成, 恆久不變."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_SWING"] =
    "法國洛可可油畫, 輕浮, 隱秘, 是那個時代最著名的圖像. 在一座蒼翠繁茂的花園裡, 一位身穿蓬鬆粉紅裙裝的少婦在繩索鞦韆上盪得高高的, 把一隻拖鞋踢向空中, 而一個藏身的老者在她身後的陰影中拉著繩索. 她年輕的情人攤躺在下方的玫瑰花叢中, 位置恰到好處, 正可仰望她的裙底, 一座石製丘比特雕像舉起一根手指抵在唇邊."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIANT_MAGNOLIAS"] =
    "美國靜物油畫, 豐潤而近乎熱帶的氣息. 兩朵碩大的乳白色木蘭花被剪下, 躺在一塊深藍色天鵝絨布的褶皺上, 四周環繞著它們光亮的深色葉片, 還有第三個尚未綻放的花苞. 花瓣在近乎全黑的背景前發著光, 以蠟質, 感官的精準筆觸繪成."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_KILLING"] =
    "加泰隆尼亞哥德式的蛋彩與金箔木板畫. 聖喬治身穿黑色盔甲, 頂著金色光環, 從他人立而起的白馬上俯身, 把一支長矛刺入一條蝙蝠翼惡龍張開的大口, 他們周圍的地面散落著骸骨和頭顱. 身著粉紅長裙的公主在身後一塊岩石高地上祈禱, 圍觀的人群擠滿了上方白色的城堡牆頭."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JACQUES_AND_BERTHE"] =
    "現代主義油畫雙人肖像, 描繪雕塑家里普希茨與其妻子, 以莫迪利亞尼一望即知的風格繪成. 丈夫身穿深色西裝站立, 一手搭在坐著的妻子肩上, 妻子雙頰泛紅的臉龐從白色蕾絲衣領上方升起. 兩人都帶有畫家標誌性的拉長臉形, 長鼻和空洞的杏仁狀眼睛, 他們的名字潦草地寫在畫布頂端."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DASH_FOR_TIMBER"] =
    "美國西部油畫, 正是那種在大眾想像中定義了舊西部的衝鋒動作場面. 八名牛仔全速朝你疾馳而來, 馬蹄離地騰空, 其中兩名騎手在馬鞍上扭身回擊身後塵土中策馬追擊的一隊阿帕奇人. 一名男子受傷癱靠在同伴身上, 眾人朝乾旱平原左緣的樹林奔去."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GEORGE_WASHINGTON_PORTRAIT"] =
    "美國油畫官方肖像, 第一任總統任期的正式形象. 喬治華盛頓身穿樸素的黑色天鵝絨禮服全身站立, 一臂前伸作演說致辭的姿態, 另一手持一柄禮儀劍, 旁邊一張桌上放著羽毛筆和墨水台. 他周圍的陳設盡是共和的莊嚴: 一把鍍金座椅飾有星條盾徽, 大理石柱, 以及一幅深紅色帷幔的褶曲, 遠處一道彩虹穿透風暴雲層而出."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ATTACK_ON_BEIJING"] =
    "日本彩色版畫, 以戰時新聞插圖的風格繪成, 配有日文和英文說明文字. 聯軍士兵強攻北京皇宮的城牆: 身穿紅外套的英軍士兵舉著米字旗從前景衝鋒, 身著白色軍服的日本步兵在右側推進. 炮彈爆炸化作一團團白煙懸在綠色的校場上空, 後方是皇宮藍頂的城門和冒煙的城牆."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUMO_WRESTLER"] =
    "日本浮世繪木刻版畫, 一幅明星力士休班時的名人肖像. 這名魁梧的男子直立全身, 在花紋長袍外罩著黑色和服, 腰帶上佩著刀, 一手以格子布巾拭額, 一手將捲起的斗篷搭在肩上. 他的名字以醒目的紅色書法欄豎排於右側, 人物造型平面而宏偉, 襯著素淨的紙地."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_TIGER_IN_TROPICAL_STORM"] =
    "素樸風格油畫, 出自一位從未見過叢林的自學成才的法國海關職員之手. 一頭睜大雙眼的老虎在被風吹打的長草中低伏, 齜牙咧嘴, 困於一場把每株植物都吹得斜倒的暴風雨中. 叢林是由綠色和紅色程式化葉片構成的密集圖案, 斜斜的銀色雨絲如薄紗般劃過整幅畫布."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_HOME_GUARD"] =
    "匈牙利畢德麥雅風格油畫肖像, 出自1848年革命. 一名蓄鬚的公民士兵身穿樸素的本色亞麻外套坐著, 兩隻戴著手套的手按在豎立的軍刀刀柄上, 袖上紅白綠三色的國民臂章宣示著他的立場. 他神情沉著堅定地望向一旁, 在深紅色帷幕前被暖光照亮, 紅色襯裡的外套搭在椅背上."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CEREMONIAL_SITTING"] =
    "俄羅斯寫實主義油畫, 規模宏大, 是帝國整個統治議會的群像. 數十位身穿深色制服, 綴滿沉重金穗帶和紅色綬帶的年長政要, 圍坐在一座白柱大廳中一圈馬蹄形排列的紅色座椅旁, 廳內懸著吊燈和皇室肖像. 六十多張面孔每一張都是獨立的肖像, 以列賓迅捷而自信的寫實筆法繪就."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUSSIAN_TSAR"] =
    "俄羅斯歷史油畫, 重現一場十六世紀的皇家巡行. 一位頭戴皮帽, 身穿金錦緞長袍的沙皇騎著一匹白馬穿過雪地, 前方有身著鮮紅外套的衛士開道, 手執高大的彎刃長戟. 人群在被踏亂的雪路兩側跪伏叩首, 蒼白冬日天空下是一座古老俄羅斯城鎮的原木建築."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CRUCIFIXION_OF_SAINT_PETER"] =
    "意大利巴洛克油畫, 以卡拉瓦喬標誌性的風格呈現的殘酷而真切的場面. 三名勞工奮力豎起一座木十字架, 年邁的聖彼得被倒釘其上, 一人拉著繩子, 另一人蜷身於橫梁之下, 他們的臉都隱沒不見. 白鬚的聖人抬起頭望向自己被釘穿的手, 他蒼老而強健的身軀在漆黑之中被一道強光照得灼然顯現."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LANDSCAPE_WITH_ANT_BEAR"] =
    "荷蘭殖民地油畫風景, 出自第一位在巴西工作的受過歐洲訓練的畫家之手. 一片陽光普照的開闊河谷在兩棵高大棕櫚樹之間向遼闊天空展開, 遠處山丘上是一座白屋構成的殖民聚落. 一群非裔巴西人扛著行囊走在前景的小徑上, 畫題中那頭長吻的食蟻獸在右下方的灌木叢中嗅探."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DUTCH_MEN_O_WAR"] =
    "荷蘭黃金時代海景油畫, 出自那個時代最偉大的船舶畫家之手. 高大的木製戰艦停泊在平滑如鏡的水面上, 船帆鬆垂, 船身倒映於海中, 每一根索具線條都精確分明. 划艇在船隻之間載送乘客, 上方是陽光照亮的大片積雲所構成的遼闊天空, 整個場景沐浴在金色的寧靜之中."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HARBOR_IN_BALAKLAVA"] =
    "克里米亞戰爭的淡彩石版畫, 出自最早一批親赴現場記錄戰役的戰地畫家之一. 在荒涼的港口岸邊, 裹著白毯的傷病士兵被人從騾子馱負的擔架上扶進一艘等候的划艇. 一群人身後是光禿的棕色山丘, 軍營小屋和帳篷點綴於山坡上, 色調低沉而具紀實感."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PEACEMAKERS"] =
    "美國歷史油畫, 描繪南北戰爭末期一場真實的軍事會議. 林肯總統坐在一艘汽船的船艙中專注聆聽, 手托下巴, 謝爾曼將軍正比劃著爭辯; 格蘭特將軍和波特海軍上將構成這四名身穿深色西裝人物的圍坐之圈. 他們身後的艙窗外, 一道彩虹穿透放晴的天空而出, 那是這幅畫對和平將臨的靜謐暗示."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_CHITASEI"] =
    "日本浮世繪木刻版畫, 出自國芳描繪中國小說水滸傳一百零八位英雄的著名系列. 足智多謀的軍師吳用身穿一襲飄逸的深色龍紋長袍站立, 在綴滿繁星的夜空下捻鬚沉思. 他身旁一座華麗的台座上立著一個碩大的天球儀, 日文題字的欄板環繞著這個人物."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_LOUIS"] =
    "十八世紀英國油畫肖像, 描繪一位雕塑家工作時的瞬間. 魯比利亞克頭戴軟帽, 身穿敞開的襯衫, 袖子捲起, 手持塑形工具停在半空, 一邊側目斜望一邊塑造著放在台架上的莎士比亞黏土小像. 雕塑家以空著的另一隻手指向自己的作品, 在昏暗的工作室背景前, 身上沐浴著溫暖的光."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_NASSER"] =
    "波斯卡扎爾王朝的宮廷油畫肖像, 王室的華貴鋪陳得厚重濃烈. 年輕的沙蓄著鬍鬚, 僵直地端坐, 身穿綴滿金線刺繡, 串串珍珠和珠寶肩章的猩紅色軍服, 繫著一條藍色綬帶, 一手按在嵌滿寶石的劍上. 他頭戴一頂高大的黑帽, 帽上插著一束鑽石飾, 描著深色眼線的雙眼望向畫外, 身後是壓印著王室銘文的深橄欖色背景."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FIELD_WITH_SHEAFS"] =
    "帶有德國表現主義傾向的油畫風景, 以寬闊而有力的筆觸繪成. 一片收割後的麥田佔滿前景, 一排排金色麥束斜倚著堆成捆束, 黃色塗抹得厚重而明亮. 一列深綠色的樹木封住田野盡頭, 上方是淡紫藍色的天空, 浮著被風吹動的雲."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AT_THE_EDGE_OF_THE_BROOK"] =
    "法國學院派油畫, 打磨得如玻璃般完美, 正是布格羅聞名於世的功夫. 兩個赤腳的農家孩子坐在溪畔的一塊石頭上, 年幼的女孩正脫下一隻長襪, 她那位深髮的同伴則撩起裙擺準備涉水. 兩人交談間互望一眼, 肌膚與蓬亂的頭髮以照片般的細膩描繪, 襯著柔和的鄉間景色."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS_ALT"] =
    "意大利浪漫主義油畫, 意大利藝術中最著名的一吻, 也是統一運動隱含的愛國象徵. 在一條中世紀的石砌走廊裡, 一個頭戴插羽帽, 身披棕色斗篷的年輕男子, 將一名女子向後扳下投入熱烈的一吻, 一隻腳已踏上樓梯, 彷彿正中途停步. 她那淡藍色緞質長裙將光傾灑入畫面, 而遠處拱門之後, 一個影影綽綽的身影正走近."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MOVING_HOUSE"] =
    "俄羅斯寫實主義油畫, 描繪寂靜的城市貧困. 一對年老的夫婦艱難地走過聖彼得堡結冰的河面, 用一個布包裹著他們全部的家當, 老人拄著一根手杖, 兩人都裹著破舊的外衣與頭巾抵禦寒冷. 一隻小狗在他們前方小跑, 身後的冬日霧靄中, 彼得保羅要塞鍍金的尖塔高高聳起."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MEXICAN_EXPEDITION"] =
    "法國海軍歷史題材油畫, 報導般的筆法, 滿是動態的場面. 一艘懸掛三色旗的法國戰艦佔據左側前景, 甲板上的軍官指揮著對墨西哥聖胡安德烏盧阿要塞的炮擊, 硝煙在水面上升起. 炮彈濺落在往返各艦運送士兵的小艇近旁, 朦朧的地平線上矗立著一座雪頂火山."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_DAY_OF_POMPEII"] =
    "巨幅畫布上的俄羅斯浪漫主義油畫, 是其所處世紀的災難史詩. 維蘇威火山爆發之際, 龐貝上空的天空燒成一片紅黑, 雕像從屋頂傾倒墜落, 閃電劈開灰雲. 成群身著羅馬服飾的城民在墜落的瓦礫間奔逃, 用斗篷護住孩童與老人, 畫面中央, 一名倒地的婦人四肢伸展, 躺在一輛傾覆的戰車旁."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ACCOLADE"] =
    "英國拉斐爾前派風格的油畫, 一幅如童話般的騎士精神圖景. 一位金髮的女王身著飄逸的白色長袍, 以劍輕觸跪地騎士的肩膀, 在小群朝臣面前為他授封. 騎士低頭垂首, 身披鎖子甲與紅色罩袍, 頭盔擱在身旁的地上, 石砌的大廳與紅色高台以柔光浪漫的細膩筆觸繪成."
